/* ===== スクロール駆動アニメーション =====
   animation-timeline: view() でコンポジタ動作。非対応ブラウザは
   @supports で除外され、コンテンツは最初から表示される。 */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    /* --- ヒーローのパララックス（ヒーローが画面外へ出る間だけ動く） --- */
    .hero-bg-gradient,
    .hero-mesh {
      animation: hero-parallax-bg linear both;
      animation-timeline: --hero;
      animation-range: exit 0% exit 100%;
    }
    .hero-content {
      /* 時間ベースの登場アニメと、スクロール連動のドリフトを併用。
         登場側は opacity/transform、ドリフト側は translate のみを
         動かすので互いに干渉しない。 */
      animation:
        hero-enter 1s ease 0.3s both,
        hero-parallax-content linear both;
      animation-timeline: auto, --hero;
      animation-range: normal, exit 0% exit 100%;
    }

    /* --- セクションのフェードイン（ビューポート進入に連動） --- */
    .stat-item,
    .section-header,
    .feature-card,
    .cta-content {
      animation: rise-in linear both;
      animation-timeline: view();
      animation-range: entry 10% cover 30%;
    }
    /* 横並び要素はレンジをずらしてスタガー */
    .stat-item:nth-child(2),
    .feature-card:nth-child(2) { animation-range: entry 18% cover 38%; }
    .stat-item:nth-child(3),
    .feature-card:nth-child(3) { animation-range: entry 26% cover 46%; }
    .stat-item:nth-child(4) { animation-range: entry 34% cover 54%; }

    /* 最終セクションはページ末尾でも完走できるよう entry のみで完結させる */
    .cta-content { animation-range: entry 10% entry 90%; }
  }
}

@keyframes hero-parallax-bg {
  to {
