const router = createRouter({
  history: createWebHistory(),
  routes,
  scrollBehavior(_to, _from, savedPosition) {
    if (savedPosition) {
      return savedPosition;
    }
    return { top: 0 };
  },
});

// metaタグを動的に更新するヘルパー
function setMeta(name, content, attr = "name") {
  let el = document.querySelector(`meta[${attr}="${name}"]`);
  if (!el) {
    el = document.createElement("meta");
    el.setAttribute(attr, name);
    document.head.appendChild(el);
  }
  el.setAttribute("content", content);
}

// canonical（正規URL）を動的に更新するヘルパー
function setCanonical(href) {
  let el = document.querySelector('link[rel="canonical"]');
  if (!el) {
    el = document.createElement("link");
    el.setAttribute("rel", "canonical");
    document.head.appendChild(el);
  }
  el.setAttribute("href", href);
}

// View Transitions API によるページ遷移アニメーション
// 非対応ブラウザ・reduced-motion 環境では通常遷移にフォールバック
let finishViewTransition;

router.beforeResolve((to, from) => {
  if (!document.startViewTransition) return;
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  // 初回ロードと、ハッシュ・クエリのみの変更は対象外
  if (from.matched.length === 0 || to.path === from.path) return;

  // 前の遷移が未完了のまま残っていたら先に完了させる（連続クリック対策）
  finishViewTransition?.();

  const domUpdated = new Promise((resolve) => {
    finishViewTransition = resolve;
  });
  document.startViewTransition(() => domUpdated);
});

router.afterEach(async () => {
  if (!finishViewTransition) return;
  // 新しいページの DOM 反映を待ってから新スナップショットを撮らせる
  await nextTick();
  finishViewTransition();
  finishViewTransition = undefined;
});

router.onError(() => {
  finishViewTransition?.();
  finishViewTransition = undefined;
});

// ページ遷移時にタイトル・metaタグを動的更新
router.afterEach((to) => {
  const baseTitle = "合同会社エクスシップス";
  const pageTitle = to.meta.title
    ? `${to.meta.title} | ${baseTitle}`
    : baseTitle;
  const description =
    to.meta.description ||
    "テクノロジーと人の力で価値を創出するITソリューション企業。スマートフォン向けアプリ開発・DevOps推進・Webサイト制作を提供します。";
  const url = BASE_URL + to.path;

  document.title = pageTitle;
  setMeta("description", description);
  setMeta("og:title", pageTitle, "property");
  setMeta("og:description", description, "property");
  setMeta("og:url", url, "property");
  setCanonical(url);
});

export default router;
